booking_source.description:
Source of the booking. Available options:
      // Đơn được tạo từ hệ thống
      System = 5,
      // Đơn được đồng bộ từ hãng
      Sync = 10,
      // Đơn được tạo từ hệ thống khác
      OtherSystem = 15,
      // Không rõ nguồn
      Unknown = 20,

booking_status.description:
Status of the booking. Available options:  
    // Nháp  
    Draft = 0,  
    // Đã gửi yêu cầu đặt vé, chờ thanh toán  
    Requested = 2,  
    // Xuất vé lỗi  
    ExportError = 6,  
    // Hết hạn do tàu đã chạy.  
    Expired = 8,  
    // Đã đặt vé  
    Booked = 10,  
    // Yêu cầu hủy đơn  
    CancelRequest = 12,  
    // Đã hủy đơn  
    Cancelled = 14,  
    // Đã hủy do tàu không khởi hành  
    CancelledBecauseBoatNotDepart = 16,

payment_status.description:
Payment status of the booking. Available options:  
    // Chưa thanh toán  
    NotPaid = 1,  
    // Thanh toán chưa đủ tiền  
    PayNotEnough = 3,  
    // Đã thanh toán, chờ đặt vé  
    Paid = 4,  
    // Đã thanh toán (công nợ), đã thanh toán cho đơn hàng nhưng khách đang nợ tiền  
    PaidWithDebt = 5,  
    // Đã hoàn tiền  
    Refunded = 18,',

